        let valid = false;
        let sourceName;
        let sourceValue;

        for(let i = 0; i < data.length; i++) {
            if(data[i][1] === valueType) {
                valid = true;
                sourceName = data[i][0];
                sourceValue = data[i][2];
                break;
            }
        }

        if (valid) {

