        //异常时标记该书,已下架
        java.put('yxj', 1);
    }

    //目录链接同书籍链接
    let tur = book.bookUrl.replace('pe":"lyc', 'pe":"l');
    //无脑更新书名
    book.name = bknm || book.name;
