				zz = zz + cnm;
				tsms && java.log('匹配5\n' + cpx + '♦' + cnm + '\nn1：' + n1 + '，n2：' + n2 + '\n' + zz);
				pji = pjr.select(`a:gt(${n1}):lt(${n2}):matchesWholeText(${zz})`).attr('href');
			}

			if (pji == '') {
