		} else if (pjfs == 2) {
			//69书吧净化
			let z1 = '[一⊥]+';
			let zz = new RegExp(`^[^，。？“”]{0,19}[6六]${z1}[9九]${z1}书${z1}吧[^，。？“”]{0,9}\$`, 'gm');
			result = result.replace(zz, '');
			//69繁体站
			if (/69shux\.co/.test(pji)) {
				let z2 = `[^\\sa-z，。？！：；…～“”、（）—‘’·《》￥〈〉【】〖〗『』「」．,?!:;…~'"一-ꀀ]|[乂爪]`;
				let z3 = "\\.*";
				let zz = new RegExp(`请${z3}您${z3}收${z3}藏${z3}6${z3}9${z3}书${z3}吧${z3}！|(?:${z2})(?:${z2}|[^\\S\\n]){6,}|^[^，。？“”]{0,9}首${z1}发${z1}内${z1}容[^，。？“”]{0,19}\$`, 'gmi');
				result = result.replace(zz, '');
			}
		} else if (pjfs == 4) {
			//篱笆好净化
			//	let fh=String.raw`[一-ꀀ\s“‘，。？！：；…—～~、’”"']`;
			let l1 = "(?:篱|li).{0,2}",
				l2 = "(?:笆|ba).{0,2}",
				l3 = "(?:好|hao).{0,2}",
				l4 = "(?:[文吻]|wen).{0,2}",
				l5 = "(?:学|xue).{0,2}",
				l6 = "(?:[好文吻学]|hao|wen|xue).{0,2}";
			let zz = new RegExp(String.raw`([^一-ꀀ])(?:</.{0,2})?(?:${l1 + l2}(?:${l6}){0,3}|${l2 + l3}(?:${l6}){0,2}|${l3 + l4}(?:${l6})?|${l4 + l5})$|${l1 + l2 + l3}(?:${l6}){0,2}$|</.{0,2}[篱笆好文学]>$`, 'gmi');
			result = result.replace(zz, '$1');
		}

		//净化标题
		if (sinfo["净化正文标题"]=="✅" && cnm && result) {
			let zz = new RegExp(String.raw`^\s*(?:${book.name}.*)?(?:</ins>\s*)?.{0,19}${cnm}(?:.{0,9}(?:[（(【].{0,39}[】)）])?\n)?`);
			result = result.replace(zz, '');
		}
		//pjfs>0结束
	} else if (pjfs==0) {java.put("nocontent",1);}
